import re,json,pathlib,hashlib
from shapely.geometry import shape
R=pathlib.Path(__file__).resolve().parents[1];s=(R/'data/raw/boundaries/seoul-grid-viewer-2025.html').read_text();raw={k:json.loads(re.search(r'const '+k+r'=(.*);',s).group(1)) for k in ['DONG','SIGUNGU']};regions=json.loads((R/'public/data/regions.json').read_text());gu={x['name']:x['code'] for x in regions['districts']};lookup={(x['districtCode'],x['name']):x['code'] for x in regions['dongs']};lookup.update({('11680','개포3동'):'11680675',('11740','상일1동'):'11740525',('11740','상일2동'):'11740526'});gushapes=[(gu[f['properties']['name']],shape(f['geometry'])) for f in raw['SIGUNGU']['features']];features=[]
for f in raw['DONG']['features']:
 geom=shape(f['geometry']);pt=geom.representative_point();matches=[code for code,g in gushapes if g.covers(pt)]
 if len(matches)!=1:matches=[max(gushapes,key=lambda item:item[1].intersection(geom).area)[0]]
 code=lookup.get((matches[0],f['properties']['name']))
 if not code:raise ValueError((matches,f['properties']))
 features.append({'type':'Feature','properties':{'code':code,'name':f['properties']['name'],'districtCode':matches[0]},'geometry':f['geometry']})
for f in raw['SIGUNGU']['features']:f['properties']['code']=gu[f['properties']['name']]
(R/'public/data/dongs.geojson').write_text(json.dumps({'type':'FeatureCollection','features':features},ensure_ascii=False,separators=(',',':')));(R/'public/data/districts.geojson').write_text(json.dumps(raw['SIGUNGU'],ensure_ascii=False,separators=(',',':')))
active={x['code']:x for x in regions['dongs'] if x.get('activePopulation',True)};codes={f['properties']['code'] for f in features};missing=[{'code':k,'name':v['name']} for k,v in active.items() if k not in codes];extra=[f['properties'] for f in features if f['properties']['code'] not in active]
meta={'sourceUrl':'https://data.seoul.go.kr/opendata/seoulStay/grid_viewer.html','sourceTitle':'서울시 공식 250m 격자 선택기 내 공개 행정동·자치구 경계','boundaryYear':2025,'boundaryDate':'2025-06-30','retrievedAt':'2026-11-14','crs':'EPSG:4326','license':'공식 공개 페이지 제공 경계. 별도 경계 라이선스 문구는 페이지에 없어 재배포 범위 확인 필요.','featureCount':len(features),'districtFeatureCount':25,'populationDongCount':len(active),'populationMatchedCount':len(codes&set(active)),'missingPopulationDongs':missing,'historicalBoundaryDongs':extra,'notes':['경계는 공식 페이지의 DONG 및 SIGUNGU GeoJSON을 변경 없이 사용. 2025-06-30 기준일은 원본 페이지에 명시.','원본 동경계 속성은 name만 제공. 공식 regions 동명과 자치구 폴리곤의 내부점을 이용해 동명을 부모구별로 구분하고 행안부 코드를 연결.','개포3동11680675/상일1동11740525/상일2동11740526은 공식 행정동 코드로 추가 연결.','2026년 생활인구 용두동11230515·신설동11230533은 이 경계에 없음. 용신동11230536 경계를 임의 분할하거나 두 동에 중복 연결하지 않음.','과거 코드 용신동은 회색 또는 데이터 없음으로 표시. 2025경계와2026통계 시점 차이를 명시할 것.'],'rawPageSha256':hashlib.sha256(s.encode()).hexdigest(),'earlierSource':'https://data.seoul.go.kr/dataList/OA-22160/S/1/datasetView.do','earlierSourceNote':'2023-10 SHP425개보다 최근인 공식2025-06 경계426개 사용'}
(R/'public/data/dongs-metadata.json').write_text(json.dumps(meta,ensure_ascii=False,indent=2));(R/'data/raw/boundaries/seoul-grid-viewer-2025.html').write_text(s);print(json.dumps(meta,ensure_ascii=False,indent=2))
